  /* ── 執行部分 ── */
  var KEYS = Object.keys(T.zh);
  function pick(code){
    for (var i = 0; i < LANGS.length; i++) if (LANGS[i].code === code) return LANGS[i];
    return null;
  }
  function detect(){
    var q = (location.search.match(/[?&]lang=([^&]+)/) || [])[1];
    if (q && pick(decodeURIComponent(q))) return decodeURIComponent(q);
    try { var s = localStorage.getItem('lang'); if (s && pick(s)) return s; } catch (e) {}
    var navs = navigator.languages || [navigator.language || 'en'];
    for (var i = 0; i < navs.length; i++) {
      var l = String(navs[i]);
      if (/^zh/i.test(l)) return /TW|HK|MO|Hant/i.test(l) ? 'zh' : (/CN|SG|Hans/i.test(l) ? 'zh-Hans' : 'zh');
      var base = l.split('-')[0].toLowerCase();
      if (pick(base)) return base;
    }
    return 'en';
  }
  var current = detect();
  function t(key, vars){
    var d = T[current] || {}, v;
    if (vars && vars.n === 1 && d[key + '1'] != null) v = d[key + '1'];
    else v = d[key] != null ? d[key] : (T.en[key] != null ? T.en[key] : (T.zh[key] != null ? T.zh[key] : key));
    if (vars) for (var k in vars) v = v.split('{' + k + '}').join(vars[k]);
    return v;
  }
  function applyStatic(){
    var els = document.querySelectorAll('[data-i18n]');
    for (var i = 0; i < els.length; i++) {
      var el = els[i], key = el.getAttribute('data-i18n'), vars = null;
      if (el.hasAttribute('data-n')) vars = { n: Number(el.getAttribute('data-n')) };
      el.innerHTML = t(key, vars);
    }
    els = document.querySelectorAll('[data-i18n-ph]');
    for (i = 0; i < els.length; i++) els[i].setAttribute('placeholder', t(els[i].getAttribute('data-i18n-ph')));
    els = document.querySelectorAll('[data-i18n-aria]');
    for (i = 0; i < els.length; i++) els[i].setAttribute('aria-label', t(els[i].getAttribute('data-i18n-aria')));
    document.title = t('title');
  }
  function set(code, persist){
    if (!pick(code)) return;
    current = code;
    var L = pick(code);
    document.documentElement.lang = L.tag;
    document.documentElement.dir = L.rtl ? 'rtl' : 'ltr';
    if (persist) try { localStorage.setItem('lang', code); } catch (e) {}
    applyStatic();
    var sel = document.getElementById('lang');
    if (sel && sel.value !== code) sel.value = code;
  }
  function tag(){ var L = pick(current); return (L ? L.tag : 'en') + '-u-nu-latn'; }
  g.I18N = { LANGS: LANGS, T: T, KEYS: KEYS, t: t, set: set, get: function(){ return current; }, tag: tag, applyStatic: applyStatic };

